template=[(-4,[-4,-2,-1,0,1,2,3,4]),(-3,[-4,-2,4]),(-2,[-4,-2,0,1,2,4]),(-1,[-4,-2,0,2,4]),(0,[-4,-2,0,2,4]),(1,[-4,-2,2,4]),(2,[-4,-2,-1,0,1,2,4]),(3,[-4,4]),(4,[-4,-3,-2,-1,0,1,2,3,4])]
S={(r,c) for r,cs in template for c in cs}
seed=(0,0)
obs={(-4,2),(-3,-3),(0,5),(1,-3),(2,4),(4,-4),(4,-1),(5,4),(6,1)}
# reachable 4-connected within S excluding obs
from collections import deque
q=deque([seed]); reach={seed}
while q:
 r,c=q.popleft()
 for p in ((r+1,c),(r-1,c),(r,c+1),(r,c-1)):
  if p in S and p not in obs and p not in reach: reach.add(p); q.append(p)
print('reach', sorted(reach))
print('by row', {r:sorted(c for rr,c in reach if rr==r) for r in range(-4,5)})

obs_test={(-4,0),(0,2),(4,4)}
q=deque([seed]); reach_test={seed}
while q:
 r,c=q.popleft()
 for p in ((r+1,c),(r-1,c),(r,c+1),(r,c-1)):
  if p in S and p not in obs_test and p not in reach_test: reach_test.add(p); q.append(p)
print({r:sorted(c for rr,c in reach_test if rr==r) for r in range(-4,5)})
# map to input output with 2s + reachable
base=[[0]*11 for _ in range(11)]
for r,c in reach_test:
 base[5+r][6+c]=3
for r,c in [(0,10),(1,1),(1,6),(3,1),(5,3),(5,8),(8,0),(9,1),(9,10),(10,6)]: base[r][c]=2
print(base)
